impl Solution {
    pub fn max_k_segments_sum(nums: Vec<i64>, m: usize, k: usize) -> i128 {
        let n = nums.len();
        // Prefix sums as i128
        let mut prefix = vec![0i128; n + 1];
        for i in 0..n {
            prefix[i + 1] = prefix[i] + nums[i] as i128;
        }
        // Helper to get window sum starting at idx
        let window_sum = |start: usize| -> i128 {
            prefix[start + m] - prefix[start]
        };
        // DP table: dp[i][j] = max sum using j segments within first i elements
        let mut dp = vec![vec![0i128; k + 1]; n + 1];
        for i in 1..=n {
            for j in 0..=k {
                // Skip current element
                dp[i][j] = dp[i - 1][j];
                // Take segment ending at i-1
                if j > 0 && i >= m {
                    let take = dp[i - m][j - 1] + window_sum(i - m);
                    if take > dp[i][j] {
                        dp[i][j] = take;
                    }
                }
            }
        }
        dp[n][k]
    }
}

